INSERT INTO dump_descriptions (base_key, description) VALUES ('pacagmas custom vanities', 'Adds custom pickaxes such as the Tonfa and Lollichop, plus vanity cosmetics including Among Us suits, barrel armor, bunny and Chernobog sets, TF2 Civilian outfits, and paintjobs.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
